function validate([operations, args]) {
  if (operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'SmallestInfiniteSet' || args[0].length !== 0) return 'Start with SmallestInfiniteSet and no arguments.';
  if (operations.length - 1 > 1000) return 'At most 1000 calls to popSmallest and addBack.';
  for (let i = 1; i < operations.length; i++) {
    if (operations[i] === 'popSmallest') { if (args[i].length !== 0) return 'popSmallest takes no arguments.'; continue; }
    if (operations[i] !== 'addBack') return 'Only popSmallest and addBack can follow the constructor.';
    const num = args[i][0];
    if (args[i].length !== 1 || !Number.isInteger(num) || num < 1 || num > 1000) return 'addBack takes one whole number from 1 to 1000.';
  }
  return null;
}

