function generate(rand, size) {
  const operations = ['SmallestInfiniteSet'];
  const args = [[]];
  const calls = size === 'large' ? 499 : 1 + Math.floor(rand() * 14);
  const top = size === 'large' ? 1000 : rand() < 0.7 ? 8 : 1000;
  const popRate = 0.3 + rand() * 0.5;
  for (let i = 0; i < calls; i++) {
    if (rand() < popRate) {
      operations.push('popSmallest');
      args.push([]);
    } else {
      operations.push('addBack');
      args.push([1 + Math.floor(rand() * top)]);
    }
  }
  return [operations, args];
}
